# Simple PowerShell HTTP Server for 21 De Valle\n$port = 8000\n$listener = New-Object System.Net.HttpListener\n$listener.Prefixes.Add(\"http://localhost:$port/\")\n$listener.Start()\n\nWrite-Host \"HTTP Server started at http://localhost:$port/\" -ForegroundColor Green\nWrite-Host \"Press Ctrl+C to stop.\" -ForegroundColor Yellow\n\n$baseDir = Get-Location\n\nwhile ($true) {\n    $context = $listener.GetContext()\n    $request = $context.Request\n    $response = $context.Response\n    \n    $url = $request.RawUrl\n    if ($url -eq \"/\") {\n        $url = \"/index.html\"\n    }\n    \n    $filePath = Join-Path $baseDir $url.TrimStart(\"/\")\n    \n    # Security: prevent path traversal\n    $fullPath = [System.IO.Path]::GetFullPath($filePath)\n    $fullBase = [System.IO.Path]::GetFullPath($baseDir)\n    \n    if (-not $fullPath.StartsWith($fullBase)) {\n        $response.StatusCode = 403\n        $response.Close()\n        continue\n    }\n    \n    if (Test-Path $filePath -PathType File) {\n        $bytes = [System.IO.File]::ReadAllBytes($filePath)\n        $response.ContentLength64 = $bytes.Length\n        \n        # Set content type based on extension\n        $ext = [System.IO.Path]::GetExtension($filePath)\n        switch ($ext) {\n            \".html\" { $response.ContentType = \"text/html\" }\n            \".css\" { $response.ContentType = \"text/css\" }\n            \".js\" { $response.ContentType = \"application/javascript\" }\n            \".png\" { $response.ContentType = \"image/png\" }\n            \".jpg\" { $response.ContentType = \"image/jpeg\" }\n            \".svg\" { $response.ContentType = \"image/svg+xml\" }\n            \".json\" { $response.ContentType = \"application/json\" }\n            default { $response.ContentType = \"application/octet-stream\" }\n        }\n        \n        $response.OutputStream.Write($bytes, 0, $bytes.Length)\n    } else {\n        $response.StatusCode = 404\n    }\n    \n    $response.Close()\n}\n"